 1→<!DOCTYPE html>
 2→<html lang="en">
 3→<head>
 4→<meta charset="UTF-8"/>
 5→<title>Playful Split Task Creator</title>
 6→<script src="https://cdn.tailwindcss.com"></script>
 7→<style>
 8→  *{box-sizing:border-box;margin:0;padding:0}
 9→  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;color:#1a1a1a;background:white;line-height:1.5}
10→  .split{display:flex;height:100vh}
11→  .left{flex:1;background:#f9f0ff;padding:2rem;display:flex;align-items:center;justify-content:center}
12→  .left h1{font-size:3rem;color:#6c4da8}
13→  .right{flex:1;padding:2rem;background:#fffbf2}
14→  .card{background:white;padding:2rem;border-radius:.75rem;box-shadow:0 2px 8px rgba(0,0,0,.1)}
15→  .input{padding:.75rem .75rem;border:1px solid #d1d5db;border-radius:.25rem;width:100%;margin-bottom:.75rem}
16→  .btn{background:#6c4da8;color:white;padding:.75rem 1rem;border:none;border-radius:.25rem;cursor:pointer}
17→  .btn:hover{background:#5e3c90}
18→  .toast{position:fixed;bottom:1rem;right:1rem;background:#6c4da8;color:white;padding:.75rem 1rem;border-radius:.25rem;display:none}
19→</style>
20→</head>
21→<body>
22→<div class="split">
23→  <div class="left"><h1>🌸</h1></div>
24→  <div class="right">
25→    <div class="card" id="taskForm">
26→      <h2 class="text-2xl mb-4">Add a new task</h2>
27→      <input type="text" id="title" placeholder="What is it?" class="input"/>
28→      <textarea id="desc" rows="3" placeholder="Tell us more" class="input"></textarea>
29→      <button id="create" class="btn">Create</button>
30→    </div>
31→  </div>
32→</div>
33→<div class="toast" id="toast">You created: "<span id="t"></span>"</div>
34→<script>
35→const toast=document.getElementById('toast');
36→const t=document.getElementById('t');
37→document.getElementById('create').addEventListener('click',()=>{
38→  const title=document.getElementById('title').value.trim();
39→  if(!title){alert('Please enter a title');return;}
40→  t.textContent=title;
41→  toast.style.display='block';
42→  setTimeout(()=>toast.style.display='none',3000);
43→});
44→</script>
45→</body>
46→</html>
